INSERT INTO coaching_chatbot.lecture_knowledge_chunks (lecture_knowledge_chunks_id,lecture_knowledge_id,chunk_index,chunk_content,qdrant_point_id,start_time_seconds,end_time_seconds,page_number,token_count,created_at) VALUES ('5cabc924-da5a-43a2-8dfa-919ba49da6e9'::uuid,'f0f814ac-a731-4f96-83e3-c1a59ee880d5'::uuid,27,'=== ORIGINAL CONTENT ===
2.3 Diagrams
17
